type Chunk = { id: string; text: string; source: string };

async function retrieve(query: string, k = 5): Promise<Chunk[]> {
  // 1. embedding of the question
  const qVec = await embedder.embed(query);

  // 2. dense search
  const dense = await vectorStore.search(qVec, { topK: k * 2 });

  // 3. lexical search (BM25) + fusion
  const lexical = await bm25.search(query, { topK: k * 2 });
  const fused = rrf([dense, lexical]);

  // 4. rerank
  const reranked = await reranker.rerank(query, fused, { topK: k });

  return reranked;
}

async function answer(query: string) {
  const chunks = await retrieve(query);
  const context = chunks.map((c) => `[${c.source}] ${c.text}`).join("\n\n");
  const prompt = `Context:\n${context}\n\nQuestion: ${query}\nAnswer citing the sources.`;
  return await llm.generate(prompt);
}
